import { isEmpty } from 'lodash-es';
import React, { RefObject, useState } from 'react';

import { useCategoricalMouseEventHandlers } from './hooks/useCategoricalMouseEventHandlers.js';
import { CategoricalBarChartInspectOverlay } from './overlays/CategoricalBarChartInspectOverlay.js';
import { ChartOverlays } from '../../../core/components/overlays/ChartOverlays.js';
import { useCategoricalBarChartBaseConfig } from '../../hooks/useCategoricalBarChartBaseConfig.js';
import { CategoricalBarChartToolbar } from '../toolbar/CategoricalBarChartToolbar.js';

interface CategoricalBarChartInteractionsProps {
  chartRef: RefObject<HTMLDivElement>;
}

export const CategoricalBarChartInteractions = (
  props: CategoricalBarChartInteractionsProps,
) => {
  const { chartRef } = props;
  const { toolbar } = useCategoricalBarChartBaseConfig();
  const shouldShowToolbar = !isEmpty(toolbar);
  const [shouldShowInspect, setShouldShowInspect] = useState(true);
  const { leave: handleOverlayLeave, move: handleOverlayMove } =
    useCategoricalMouseEventHandlers();

  const handleMouseEnter = () => {
    setShouldShowInspect(false);
  };

  const handleMouseLeave = () => {
    setShouldShowInspect(true);
  };

  return (
    <ChartOverlays
      onMouseLeave={handleOverlayLeave}
      onMouseMove={handleOverlayMove}
      tooltipContainerRef={chartRef}
    >
      {shouldShowInspect && <CategoricalBarChartInspectOverlay />}
      {shouldShowToolbar && (
        <CategoricalBarChartToolbar
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
        />
      )}
    </ChartOverlays>
  );
};

CategoricalBarChartInteractions['displayName'] =
  'CategoricalBarChartInteractions';
